package org.pokemonx.recomp;
import java.io.*;import java.nio.file.*;import java.util.*;import java.util.zip.*;
public class FileFeaturesTest{
 static File zip(Path dir,String name,String entry,byte[]data)throws Exception{File f=dir.resolve(name).toFile();try(ZipOutputStream z=new ZipOutputStream(new FileOutputStream(f))){z.putNextEntry(new ZipEntry(entry));z.write(data);z.closeEntry();}return f;}
 public static void main(String[]args)throws Exception{
  Path temp=Files.createTempDirectory("px-files-test");File files=temp.resolve("files").toFile(),data=SaveManager.data(files),save=new File(data,"00000001");save.mkdirs();byte[]original={1,2,3,4};Files.write(new File(save,"main").toPath(),original);Files.write(new File(data,"00000001.metadata").toPath(),new byte[16]);File backup=temp.resolve("export.zip").toFile();SaveManager.exportSave(files,new FileOutputStream(backup));File replacement=temp.resolve("main").toFile();Files.write(replacement.toPath(),new byte[]{5,6});SaveManager.importSave(replacement,files);if(!Arrays.equals(Files.readAllBytes(new File(SaveManager.data(files),"00000001/main").toPath()),new byte[]{5,6})||SaveManager.latestBackup(files)==null)throw new AssertionError();SaveManager.importSave(backup,files);if(!Arrays.equals(Files.readAllBytes(new File(SaveManager.data(files),"00000001/main").toPath()),original))throw new AssertionError("roundtrip");
  File bad=zip(temp,"bad-save.zip","../main",new byte[]{9});try{SaveManager.importSave(bad,files);throw new AssertionError();}catch(IOException expected){}if(!Arrays.equals(Files.readAllBytes(new File(SaveManager.data(files),"00000001/main").toPath()),original))throw new AssertionError("bad import changed save");
  byte[]png=new byte[24];java.nio.ByteBuffer h=java.nio.ByteBuffer.wrap(png);h.putLong(0x89504e470d0a1a0aL).putInt(13).putInt(0x49484452).putInt(8).putInt(8);String name="tex1_8x8_0000000000000001_13_mip0.png";File pack=zip(temp,"pack.zip","Nested/"+name,png);if(ModInstaller.install(pack,files,"Synthetic")!=1||!ModInstaller.installed(files))throw new AssertionError();File oldTexture=new File(ModInstaller.directory(files),name);byte[]before=Files.readAllBytes(oldTexture.toPath());
  for(File invalid:new File[]{zip(temp,"traverse.zip","../../"+name,png),zip(temp,"code.zip","code.ips",new byte[]{1}),zip(temp,"corrupt.zip",name,new byte[]{0})}){try{ModInstaller.install(invalid,files,"Invalid");throw new AssertionError("bad mod accepted");}catch(IOException expected){}if(!Arrays.equals(Files.readAllBytes(oldTexture.toPath()),before))throw new AssertionError("bad mod changed installation");}
  System.out.println("PASS save ZIP roundtrip, raw main restore, automatic backup, traversal rejection and original save preservation; texture-pack install, code/corrupt/traversal rejection and old pack preservation");UpdateInstaller.remove(temp.toFile());
 }
}
